questionvariables.text:
cosd(x) := cos(x*%pi/180);
sind(x) := sin(x*%pi/180);
atand(x) := 180*atan(x)/%pi;
asind(x) := 180*asin(x)/%pi;
two(v) := if v < 10 then sconcat("0", string(v)) else string(v);
hm(m) := block([q], q: mod(m, 1440), sconcat(two(floor(q/60)), ":", two(mod(q, 60))));
dmx(m) := sconcat(string(floor(m/60)), "^\\circ", two(mod(m, 60)), "'");
/* Design: [l1, l2 (signed, east positive), speed in knots, departure h, m]. Times in minutes. No entry should repeat the worked example A Westward Flight. Source: original. */
L: [[37,10,360,7,30],[37,-5,480,9,0],[0,37,400,6,15],[3,40,440,6,30],[-20,30,500,12,0],[37,15,440,13,20],[9,37,420,10,10],[45,10,420,15,0],[37,-10,470,11,30],[-15,20,350,5,45]];
ix: 1+rand(10);
E: L[ix];
v: E[3];
dl: E[2]-E[1];
east: is(dl>0);
nm: 60*abs(dl);
fl: nm/v*60;
dep: 60*E[4]+E[5];
arr: dep+fl+4*dl;
fr: floor(fl+1/2); ar: floor(arr+1/2);
/* diagnostics */
noadj: dep+fl; dirw: dep+fl-4*dl;

feedbackvariables.text:
T1: 60*ans1+ans2;
c1: is(abs(T1-fl)<=1/2 and ans2<60 and ans2>=0);
f1: is(abs(T1-fl)<=1/2);
yd: float(T1*v/60);

T1: 60*ans1+ans2;
T2: 60*ans3+ans4;
ya: T2-dep-T1;
c2: is(abs(T2-arr)<=1/2 and ans4<60 and ans4>=0 and ans3<24);
f2: is(abs(T2-arr)<=1/2);
n2: is(abs(T2-noadj)<=1);
w2: is(abs(T2-dirw)<=1);
ft2: is(abs(T1-fl)>1/2 and abs(T2-(dep+T1+4*dl))<=1/2);
